parameters.jsCode:
const cfg = $input.first().json;
for (const key of ['accountUid', 'folderUid']) if (!cfg[key] || cfg[key].startsWith('YOUR_')) throw new Error(`Replace ${key} in Settings before running.`);
if (typeof cfg.question !== 'string' || !cfg.question.trim() || cfg.question.length > 2000) throw new Error('Enter a question of 1–2000 characters in Settings.');
return [{json: cfg}];
